import java.util.*;
public class Main {static class Fast {byte[] b=new byte[65536];int p,l;int read()throws Exception{if(p==l){l=System.in.read(b);p=0;if(l<0)return -1;}return b[p++];}String next()throws Exception{StringBuilder s=new StringBuilder();int c;do{c=read();}while(c<=32&&c!=-1);while(c>32){s.append((char)c);c=read();}return s.toString();}int number()throws Exception{return Integer.parseInt(next());}}
 static class Crane {int l,r;long count;Crane(int a,int b,long c){l=a;r=b;count=c;}}
 public static void main(String[] args)throws Exception{Fast in=new Fast();int t=in.number();StringBuilder out=new StringBuilder();while(t-->0){int n=in.number(),m=in.number();long[] health=new long[n+1],expire=new long[n+2];for(int i=1;i<=n;i++)health[i]=in.number();Crane[] cranes=new Crane[m];for(int i=0;i<m;i++)cranes[i]=new Crane(in.number(),in.number(),in.number());Arrays.sort(cranes,Comparator.comparingInt(c->c.l));PriorityQueue<Crane> active=new PriorityQueue<>((a,b)->Integer.compare(b.r,a.r));int at=0;long beams=0,damage=0;boolean possible=true;for(int i=1;i<=n;i++){damage+=expire[i];while(at<m&&cranes[at].l<=i)active.add(cranes[at++]);long need=health[i]-damage;while(need>0){while(!active.isEmpty()&&(active.peek().r<i||active.peek().count==0))active.poll();if(active.isEmpty()){possible=false;break;}Crane c=active.peek();long take=Math.min(need,c.count);c.count-=take;need-=take;damage+=take;beams+=take;expire[c.r+1]-=take;}if(!possible)break;}if(possible)out.append("YES ").append(beams);else out.append("NO");out.append('\n');}System.out.print(out);}}
